#include <stdio.h>

int main(void)
{
    int a = 2;
    int b = 3;
    int c = 4;
    int normal_precedence = a + b * c;
    int explicit_grouping = (a + b) * c;
    printf("normal=%d\n", normal_precedence);
    printf("grouped=%d\n", explicit_grouping);
    return 0;
}
